const body = $json.body || $json;

const answers = body.answers || {};
const contact = body.contact || {};
const source = body.source || {};
const meta = body.meta || {};

// CR-005: интерес по конкретному документу
const documentInterest = answers.document_interest || "";

const documentInterestLabels = {
  reporting: "Отчетность",
  waste: "Отходы",
  emissions: "Выбросы в воздух",
  water_subsoil: "Сбросы воды / скважина / недра",
  inspection: "Проверка / штраф",
  unknown: "Не знаю, что именно нужно"
};

const documentInterestLabel = documentInterestLabels[documentInterest] || "";

// Сокращенный сценарий: пользователь выбрал конкретный документ и сразу перешел к контактам.
// В этом сценарии мы НЕ знаем сегмент, ответственного, срочность и ES-потенциал.
// Поэтому не подставляем ложные значения "Никто", "В течение месяца" и т.д.
const isDocumentFlow = !!documentInterest && documentInterest !== "unknown";

// ---------- Raw values ----------
const objectType = answers.object_type || (isDocumentFlow ? "Другое" : "");
const features = Array.isArray(answers.object_features) ? answers.object_features : [];
const sitesCountRaw = answers.sites_count || "1";

const responsibleRaw = answers.ecology_responsible || "";
const situation = answers.main_situation || "";
const urgencyRaw = answers.urgency || "";
const helpFormat = answers.help_format || "";

// ---------- Complexity ----------
let complexityScore = 0;

if (!isDocumentFlow) {
  if (objectType === "Производство") complexityScore += 30;
  if (objectType === "Стройка") complexityScore += 20;
  if (objectType === "Автосервис / СТО" || objectType === "СТО") complexityScore += 15;
  if (objectType === "Автомойка") complexityScore += 15;
  if (objectType === "Склад") complexityScore += 10;
  if (objectType === "Магазин / торговля" || objectType === "Торговля") complexityScore += 5;

  if (features.includes("Мусор и упаковка")) complexityScore += 10;
  if (features.includes("Масла / ветошь") || features.includes("Масла, тряпки, фильтры")) complexityScore += 15;
  if (features.includes("Выбросы в воздух")) complexityScore += 25;
  if (features.includes("Сброс воды") || features.includes("Сточные воды")) complexityScore += 35;

  if (sitesCountRaw === "2-3" || sitesCountRaw === "2–3 площадки" || sitesCountRaw === "2-3 площадки") complexityScore += 25;
  if (sitesCountRaw === "4+" || sitesCountRaw === "4 и более площадок") complexityScore += 40;

  if ((objectType === "Автосервис / СТО" || objectType === "СТО") && features.some(f => f.includes("Масла"))) {
    complexityScore += 15;
  }

  if (objectType === "Производство" && features.some(f => f.includes("Масла"))) {
    complexityScore += 35;
  }

  if (objectType === "Производство" && features.includes("Выбросы в воздух")) {
    complexityScore += 25;
  }

  if (objectType === "Производство" && (features.includes("Сброс воды") || features.includes("Сточные воды"))) {
    complexityScore += 35;
  }
}

let complexity = "Простой";
if (complexityScore >= 70) complexity = "Сложный";
else if (complexityScore >= 30) complexity = "Средний";

// ---------- Urgency ----------
let urgencyScore = 0;

if (!isDocumentFlow) {
  if (urgencyRaw === "В этом году" || urgencyRaw === "Не срочно") urgencyScore += 10;
  if (urgencyRaw === "В течение квартала") urgencyScore += 25;
  if (urgencyRaw === "В течение месяца" || urgencyRaw === "В ближайшие недели") urgencyScore += 40;
  if (urgencyRaw === "Срочно" || urgencyRaw === "Очень срочно") urgencyScore += 60;
  if (situation === "Проверка или предписание") urgencyScore += 70;
}

let urgency = "Низкая";
if (urgencyScore >= 60) urgency = "Высокая";
else if (urgencyScore >= 20) urgency = "Средняя";

// ---------- ES Potential ----------
let esScore = 0;

if (!isDocumentFlow) {
  if (responsibleRaw === "Подрядчик") esScore += 10;
  if (responsibleRaw === "Охрана труда" || responsibleRaw === "Специалист по охране труда") esScore += 20;
  if (responsibleRaw === "Бухгалтер") esScore += 35;
  if (responsibleRaw === "Директор") esScore += 40;
  if (responsibleRaw === "Никто") esScore += 45;

  if (helpFormat === "Чтобы кто-то полностью занимался экологией") esScore += 60;
  if (helpFormat === "Чтобы специалист сделал конкретный документ" || helpFormat === "Нужна конкретная услуга") esScore += 25;
  if (helpFormat === "Чтобы специалист подсказал, что нужно" || helpFormat === "Нужна консультация") esScore += 20;
  if (helpFormat === "Пока не решили") esScore += 10;
  if (situation === "Проверка или предписание") esScore += 30;

  if ((sitesCountRaw === "2-3" || sitesCountRaw === "4+") && responsibleRaw === "Никто") {
    esScore += 30;
  }
}

let esPotential = "Низкий";
if (esScore >= 70) esPotential = "Высокий";
else if (esScore >= 30) esPotential = "Средний";

// ---------- DIY ----------
let diyScore = 0;

if (!isDocumentFlow) {
  if (helpFormat === "Разобраться самому" || helpFormat === "Хочу разобраться сам") diyScore += 60;
  if (situation === "Пока изучаем") diyScore += 20;
  if (helpFormat === "Пока не решили") diyScore += 10;
}

let diyLevel = "Низкий";
if (diyScore >= 60) diyLevel = "Высокий";
else if (diyScore >= 30) diyLevel = "Средний";

// ---------- Route ----------
const hasEmissions = features.includes("Выбросы в воздух");
const hasDischarge = features.includes("Сброс воды") || features.includes("Сточные воды");

const multiSite =
  sitesCountRaw === "2-3" ||
  sitesCountRaw === "4+" ||
  sitesCountRaw === "2-3 площадки" ||
  sitesCountRaw === "4 и более площадок";

let route = "Услуга";

if (isDocumentFlow) {
  route = "Услуга";
} else if (
  complexity === "Сложный" ||
  (objectType === "Производство" && hasEmissions && hasDischarge) ||
  (hasEmissions && hasDischarge) ||
  (multiSite && (
    responsibleRaw === "Никто" ||
    situation === "Не знаем что нужно сдавать" ||
    situation === "Не понимаю что требуется"
  ))
) {
  route = "Консультация";
} else if (esPotential === "Высокий") {
  route = "Потенциал ЭС";
} else if (diyLevel === "Высокий" && urgency !== "Высокая") {
  route = "Самостоятельно";
}

// ---------- Priority ----------
let priority = "Средний";

if (isDocumentFlow) {
  priority = documentInterest === "inspection" ? "Высокий" : "Средний";
} else if (
  situation === "Проверка или предписание" ||
  urgency === "Высокая" ||
  complexity === "Сложный" ||
  esPotential === "Высокий"
) {
  priority = "Высокий";
} else if (diyLevel === "Высокий" && urgency === "Низкая") {
  priority = "Низкий";
}

// ---------- Object count ----------
let objectCount = "1 площадка";

if (sitesCountRaw === "2-3" || sitesCountRaw === "2–3 площадки" || sitesCountRaw === "2-3 площадки") {
  objectCount = "2-3 площадки";
}

if (sitesCountRaw === "4+" || sitesCountRaw === "4 и более площадок") {
  objectCount = "4 и более площадок";
}

// ---------- Tags ----------
const tags = [];

if (objectType === "Производство") tags.push("production");
if (objectType === "Склад") tags.push("warehouse");
if (objectType === "Стройка") tags.push("construction");
if (objectType === "Автосервис / СТО" || objectType === "СТО") tags.push("car_service");
if (objectType === "Автомойка") tags.push("car_wash");

if (!isDocumentFlow) {
  if (responsibleRaw === "Никто") tags.push("no_ecologist");
  if (responsibleRaw === "Бухгалтер") tags.push("accountant_responsible");
  if (responsibleRaw === "Директор") tags.push("director_responsible");

  if (urgency === "Высокая") tags.push("urgent");
  if (situation === "Проверка или предписание") tags.push("inspection_risk");
  if (esPotential === "Высокий") tags.push("high_es");
  if (diyLevel === "Высокий") tags.push("diy");
  if (multiSite) tags.push("multi_site");
}

if (documentInterest) {
  tags.push("document_interest_" + documentInterest);
}

if (isDocumentFlow) {
  tags.push("short_document_flow");
}

// ---------- IDs for Bitrix ----------
const ids = {
  segment: {
    "Производство": 3948,
    "Склад": 3949,
    "Стройка": 3950,
    "Автосервис / СТО": 3951,
    "СТО": 3951,
    "Автомойка": 3952,
    "Магазин / торговля": 3953,
    "Торговля": 3953,
    "Офис": 3954,
    "ЖКХ": 3955,
    "Сельхоз": 3956,
    "Другое": 3957
  },
  complexity: {
    "Простой": 3958,
    "Средний": 3959,
    "Сложный": 3960
  },
  priority: {
    "Низкий": 3964,
    "Средний": 3965,
    "Высокий": 3966
  },
  route: {
    "Услуга": 3970,
    "Консультация": 3971,
    "Самостоятельно": 3972,
    "Потенциал ЭС": 3973
  },
  diy: {
    "Низкий": 3974,
    "Средний": 3975,
    "Высокий": 3976
  },
  responsible: {
    "Штатный эколог": 3987,
    "Бухгалтер": 3988,
    "Директор": 3989,
    "Охрана труда": 3990,
    "Специалист по охране труда": 3990,
    "Подрядчик": 3991,
    "Никто": 3992
  },
  urgency: {
    "Низкая": 3993,
    "Средняя": 3994,
    "Высокая": 3995
  },
  object_count: {
    "1 площадка": 3996,
    "2-3 площадки": 3997,
    "4 и более площадок": 3998
  }
};

// ---------- Texts ----------
const documentLine = documentInterestLabel
  ? `Интерес по документу: ${documentInterestLabel}. `
  : "";

const summary = isDocumentFlow
  ? `${documentLine}Пользователь выбрал сокращенный сценарий “Нужен конкретный документ”. Детальная квалификация объекта не проходилась.`
  : `${documentLine}${objectType || "Объект не указан"}. ` +
    `Ответственный за экологию: ${responsibleRaw || "не указан"}. ` +
    `Факторы: ${features.join(", ") || "не указаны"}. ` +
    `Срочность: ${urgencyRaw || "не указана"}. ` +
    `Формат помощи: ${helpFormat || "не указан"}.`;

const adminHint = documentInterestLabel
  ? `Уточнить, какой именно документ нужен по направлению: ${documentInterestLabel}. Затем квалифицировать клиента по стандартному скрипту: регион, юрлицо, кто принимает решение, сроки, действующие документы.`
  : `Уточнить регион, юрлицо, кто принимает решение, есть ли действующие документы и сроки.`;

const salesHint = isDocumentFlow
  ? "Клиент пришел за конкретным документом. Сначала уточнить потребность и контекст. Не делать вывод о потенциале ЭС без дополнительной квалификации."
  : esPotential === "Высокий"
    ? "Есть потенциал ЭС. Не продавать только разовую услугу, мягко вывести на консультацию и аутсорс экологии."
    : "Обработать по маршруту, уточнить потребность и ближайший следующий шаг.";

// ---------- Return ----------
return [
  {
    json: {
      session_id: body.session_id,

      name: contact.name,
      phone: contact.phone_or_whatsapp,
      telegram: contact.telegram || "",
      comment: contact.comment || "",

      segment: objectType,
      segment_id: ids.segment[objectType] || null,

      complexity,
      complexity_id: ids.complexity[complexity] || null,

      priority,
      priority_id: ids.priority[priority] || null,

      es_potential: esPotential,
      es_potential_id: null,

      route,
      route_id: ids.route[route] || null,

      diy_level: diyLevel,
      diy_level_id: ids.diy[diyLevel] || null,

      responsible: responsibleRaw,
      responsible_id: ids.responsible[responsibleRaw] || null,

      urgency,
      urgency_id: ids.urgency[urgency] || null,

      object_count: objectCount,
      object_count_id: ids.object_count[objectCount] || null,

      document_interest: documentInterest,
      document_interest_label: documentInterestLabel,

      tags: tags.join(","),

      summary,
      admin_hint: adminHint,
      sales_hint: salesHint,

      entry_type: source.entry_type,
      page_url: source.page_url,
      page_title: source.page_title,
      page_type: source.page_type,
      started_at: meta.started_at,
      completed_at: meta.completed_at,
      device: meta.device
    }
  }
];

