const ai = $json.output?.[0]?.content?.[0]?.text || {};

return [
  {
    json: {
      ...$('Normalize + Scoring').first().json,

      summary: ai.summary || $('Normalize + Scoring').first().json.summary,
      admin_hint: ai.admin_hint || $('Normalize + Scoring').first().json.admin_hint,
      sales_hint: ai.sales_hint || $('Normalize + Scoring').first().json.sales_hint
    }
  }
];
